`),$t("skill-creator","\u5F15\u5BFC\u7528\u6237\u521B\u5EFA / \u67E5\u770B\u81EA\u5B9A\u4E49\u6280\u80FD\u6587\u4EF6\uFF08AI \u52A9\u624B/skills \u76EE\u5F55\u4E0B\u7684 SKILL.md\uFF09\u3002",["create_note","read_note","search_notes"],`
